import os
from pathlib import Path

import boto3
from dotenv import load_dotenv

# app/.env is generated by `terraform apply` (terraform/app_config.tf).
load_dotenv(Path(__file__).resolve().parents[1] / ".env")


def get_config() -> dict:
    return {
        "region": os.environ["AWS_REGION"],
        "docs_bucket": os.environ["DOCS_BUCKET_NAME"],
        "knowledge_base_id": os.environ["KNOWLEDGE_BASE_ID"],
        "data_source_id": os.environ["DATA_SOURCE_ID"],
        "generation_model_arn": os.environ["GENERATION_MODEL_ARN"],
        # Optional: leave empty to disable reranking.
        "rerank_model_arn": os.environ.get("RERANK_MODEL_ARN", ""),
        # Optional: only needed for the "Agentic RAG" comparison feature.
        "agent_runtime_arn": os.environ.get("AGENT_RUNTIME_ARN"),
    }


def get_s3_client():
    return boto3.client("s3", region_name=get_config()["region"])


def get_bedrock_agent_client():
    return boto3.client("bedrock-agent", region_name=get_config()["region"])


def get_bedrock_agent_runtime_client():
    return boto3.client("bedrock-agent-runtime", region_name=get_config()["region"])


def get_bedrock_agentcore_client():
    return boto3.client("bedrock-agentcore", region_name=get_config()["region"])
